window.QUESTIONS_KOUNEN = [{"id": 1, "section": "総則", "q": "厚生年金保険法第1条において、「この法律は、労働者の老齢、障害、出産又は死亡について保険給付を行い、労働者及びその遺族の生活の安定と福祉の向上に寄与することを目的とする。」と規定されている。", "correct": false, "exp": "厚生年金保険は、労働者の出産について保険給付を行わない。"}, {"id": 2, "section": "総則", "q": "厚生年金保険は、日本年金機構が、管掌する。", "correct": false, "exp": "厚生年金保険は、「政府」が、管掌する。"}, {"id": 3, "section": "総則", "q": "厚生年金保険法に規定する厚生労働大臣の権限は、市町村長に委任することができる。", "correct": false, "exp": "厚生労働大臣の権限は、日本年金機構、財務大臣又は地方厚生局長等へ委任することができるが、市町村長へ委任することができるとする規定はない。"}, {"id": 4, "section": "適用事業所", "q": "常時5人以上の従業員を使用する法人でない個人事業所のうち、旅館、料理店、飲食店等のサービス業を行うものは強制適用事業所とはならない。", "correct": true, "exp": "旅館、料理店、飲食店等の非適用業種を行う個人事業所は、常時5人以上の従業員を使用する場合であっても、強制適用事業所とはならない。"}, {"id": 5, "section": "適用事業所", "q": "法人の事業所であって、常時3人の従業員を使用するものは、任意適用事業所の認可を受けなければ適用事業所となることはない。", "correct": false, "exp": "法人の事業所であって、常時従業員を使用するものは、強制適用事業所とされる。"}, {"id": 6, "section": "適用事業所", "q": "常時使用している船員（船員法第1条に規定する船員）が5人から4人に減少した船舶所有者は、その事業所を適用事業所とするためには任意適用事業所の認可を受けなければならない。", "correct": false, "exp": "船員法第1条に規定する船員として船舶所有者に使用される者が乗り組む船舶は、強制適用事業所とされる。"}, {"id": 7, "section": "適用事業所", "q": "厚生年金保険法第6条第3項に定める任意適用事業所となる認可を受けようとするときは、当該事業所の事業主は、当該事業所に使用される者の3分の2以上の同意を得て、厚生労働大臣に申請しなければならない。", "correct": false, "exp": "設問の認可を受けようとする事業主は、使用される者の「2分の1」以上の同意を得て、厚生労働大臣に申請しなければならない。"}, {"id": 8, "section": "適用事業所", "q": "任意適用事業所の事業主が当該事業所を適用事業所でなくする認可を受けようとするときは、当該事業所に使用される者の2分の1以上の同意を得て、厚生労働大臣に申請しなければならない。", "correct": false, "exp": "設問の認可を受けようとする事業主は、使用される者の「4分の3」以上の同意を得て、厚生労働大臣に申請しなければならない。"}, {"id": 9, "section": "適用事業所", "q": "2以上の適用事業所（船舶を除く。）の事業主が同一である場合には、当該事業主は、厚生労働大臣の承認を受けて、当該2以上の事業所を1つの適用事業所とすることができる。", "correct": true, "exp": "設問の通り正しい。なお、設問の承認があったときは、当該2以上の適用事業所は、適用事業所でなくなったものとみなされる。"}, {"id": 10, "section": "適用事業所", "q": "2以上の船舶の船舶所有者が同一である場合には、当該船舶所有者は、厚生労働大臣の認可を受けて、当該2以上の船舶を1つの適用事業所とすることができる。", "correct": false, "exp": "2以上の船舶の船舶所有者が同一である場合には、当該2以上の船舶は、法律上当然に1つの適用事業所とされる。"}, {"id": 11, "section": "適用事業所", "q": "強制適用事業所（船舶を除く。）がその要件に該当しなくなったときは、任意適用事業所の認可があったものとみなされ、引き続き適用事業所となる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 12, "section": "被保険者", "q": "更生保護事業法に定める更生保護事業の事業所であって、常時5人以上の従業員を使用する事業所に使用される70歳未満の者は、被保険者とされる。", "correct": true, "exp": "設問の通り正しい。設問の事業所は強制適用事業所である。"}, {"id": 13, "section": "被保険者", "q": "地方公務員共済組合の組合員である厚生年金保険の被保険者を、第3号厚生年金被保険者という。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 14, "section": "被保険者", "q": "私立学校教職員共済制度の加入者である厚生年金保険の被保険者を、第2号厚生年金被保険者という。", "correct": false, "exp": "私立学校教職員共済制度の加入者である厚生年金保険の被保険者を、第4号厚生年金被保険者という。"}, {"id": 15, "section": "被保険者", "q": "任意適用事業所の認可を受けた個人事業所の事業主は、被保険者とされる。", "correct": false, "exp": "個人事業所の事業主は、被保険者とされない。"}, {"id": 16, "section": "被保険者", "q": "巡回興業など所在地が一定しない事業に使用される者については、当初から継続して6月を超えて使用される予定である場合でも、被保険者になることができない。", "correct": true, "exp": "設問の者は、適用除外に該当するため、その使用期間の長短にかかわらず、被保険者になることはできない。"}, {"id": 17, "section": "被保険者", "q": "2月以内の期間を定めて適用事業所に臨時に使用される70歳未満の者（船舶所有者に使用される船員を除く。）であって、当該定めた期間を超えて使用されることが見込まれないものは、当該定めた期間を超え、引き続き使用されるに至った場合を除き、被保険者とならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 18, "section": "被保険者", "q": "季節的業務に使用される者（船舶所有者に使用される船員を除く。）は、当初から継続して6か月を超えて使用されるべき場合を除き、被保険者とならない。", "correct": false, "exp": "季節的業務に使用される者（船舶所有者に使用される船員を除く。）は、当初から継続して「4か月」を超えて使用されるべき場合を除き、被保険者とならない。"}, {"id": 19, "section": "被保険者", "q": "臨時的事業の事業所に使用される者であって、その者が継続して6か月を超えない期間使用される場合は、厚生年金保険の被保険者とならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 20, "section": "被保険者", "q": "短時間労働者が被保険者となるための要件の一つとして、「報酬について、資格取得時決定の規定の例により算定した額が、98,000円以上であること。」が挙げられる。", "correct": false, "exp": "要件の一つとして、「報酬について、資格取得時決定の規定の例により算定した額が、88,000円以上であること。」が挙げられる。"}, {"id": 21, "section": "被保険者", "q": "1週間の所定労働時間及び1か月間の所定労働日数が、ともに同一の事業所に使用される通常の労働者の4分の3以上であっても大学の学生であれば、厚生年金保険の被保険者とならない。", "correct": false, "exp": "1週間の所定労働時間及び1か月間の所定労働日数が、ともに通常の労働者の4分の3以上である者は、大学の学生であっても、厚生年金保険の被保険者となり得る。"}, {"id": 22, "section": "被保険者", "q": "適用事業所以外の事業所に使用される70歳未満の者は、その事業所の事業主の同意を得た上で厚生労働大臣の認可を受けて、任意単独被保険者となることができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 23, "section": "被保険者", "q": "適用事業所以外の事業所に使用される高齢任意加入被保険者は、加入の際には、事業主の同意を得たうえで、厚生労働大臣に申出を行うという手続きを行っている。", "correct": false, "exp": "適用事業所以外の事業所に使用される高齢任意加入被保険者となるためには、事業主の同意を得た上で、厚生労働大臣の認可を受けなければならない。"}, {"id": 24, "section": "被保険者", "q": "適用事業所に使用される70歳以上の者であって、老齢厚生年金等の受給権を有しないものが、高齢任意加入被保険者の資格を取得するためには、事業主の同意を得る必要はないが、実施機関に申し出る必要がある。", "correct": true, "exp": "設問の通り正しい。適用事業所に使用される70歳以上の者が高齢任意加入被保険者となるための申出をする際に、事業主の同意を得る必要はない。"}, {"id": 25, "section": "被保険者", "q": "任意単独被保険者は、厚生労働大臣の認可を受けた日の翌日に、被保険者の資格を取得する。", "correct": false, "exp": "任意単独被保険者は、厚生労働大臣の認可を受けた日に、被保険者の資格を取得する。"}, {"id": 26, "section": "被保険者", "q": "被保険者が死亡したときは、死亡した日に、被保険者の資格を喪失する。", "correct": false, "exp": "被保険者が死亡したときは、死亡した日の翌日に、被保険者の資格を喪失する。"}, {"id": 27, "section": "被保険者", "q": "昭和30年4月1日生まれの当然被保険者は、令和7年4月1日に70歳に達し、その日に被保険者の資格を喪失する。", "correct": false, "exp": "昭和30年4月1日生まれの当然被保険者は、令和7年3月31日に70歳に達し、その日に被保険者の資格を喪失する。"}, {"id": 28, "section": "被保険者", "q": "適用事業所に使用される高齢任意加入被保険者が、初めて納付すべき保険料を滞納し、督促状の指定期限までに、その保険料を納付しないときは、その者の事業主が当該高齢任意加入被保険者に係る保険料の半額負担及び納付義務を負うことについて同意をしているときを除き、高齢任意加入被保険者とならなかったものとみなす。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 29, "section": "被保険者", "q": "高齢任意加入被保険者を使用する適用事業所の事業主が、当該高齢任意加入被保険者に係る保険料の半額負担及び納付義務を負うことについての同意を撤回したときは、その撤回をした日の翌日に、高齢任意加入被保険者はその資格を喪失する。", "correct": false, "exp": "設問の同意の撤回は、高齢任意加入被保険者の資格喪失事由に該当しない。"}, {"id": 30, "section": "被保険者", "q": "第1号厚生年金被保険者が同時に第2号厚生年金被保険者、第3号厚生年金被保険者又は第4号厚生年金被保険者の資格を有するに至ったときは、その日に、当該第1号厚生年金被保険者の資格を喪失する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 31, "section": "被保険者期間等", "q": "第1号厚生年金被保険者に係る資格の得喪の確認は、事業主の届出若しくは被保険者等の請求により、又は厚生労働大臣の職権で行うものとされている。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 32, "section": "被保険者期間等", "q": "適用事業所に使用される高齢任意加入被保険者（第1号厚生年金被保険者とする。）が、その事業所に使用されなくなったことにより被保険者の資格を喪失したときは、厚生労働大臣の確認を要しない。", "correct": false, "exp": "設問の場合には、厚生労働大臣（日本年金機構）の確認を要する。なお、設問の高齢任意加入被保険者が、資格喪失の申出が受理されたことによりその資格を喪失したときは、厚生労働大臣（日本年金機構）の確認を要しない。"}, {"id": 33, "section": "被保険者期間等", "q": "厚生年金保険法で定める「被保険者期間」とは、被保険者の資格を取得した月の翌月から被保険者の資格を喪失した月までの月単位で計算された期間である。", "correct": false, "exp": "「被保険者期間」とは、原則として、被保険者の資格を取得した月から被保険者の資格を喪失した月の前月までの月単位で計算された期間である。"}, {"id": 34, "section": "被保険者期間等", "q": "昭和61年4月1日から平成3年3月31日まで第3種被保険者であった者の被保険者期間は、実期間を5分の6倍して計算される。", "correct": true, "exp": "設問の通り正しい。なお、昭和61年4月1日前までの第3種被保険者であった期間については、その期間を3分の4倍して厚生年金保険の被保険者期間を計算する。"}, {"id": 35, "section": "届出等", "q": "初めて適用事業所となった船舶の船舶所有者は、当該事実があった日から5日以内に、所定の事項を記載した届書を日本年金機構に提出しなければならない。", "correct": false, "exp": "初めて適用事業所となった船舶の船舶所有者は、当該事実があった日から「10日以内」に、所定の事項を記載した届書を日本年金機構に提出しなければならない。"}, {"id": 36, "section": "届出等", "q": "適用事業所の事業主（船舶所有者を除く。）は、廃止、休止その他の事情により適用事業所に該当しなくなったときは、当該事実があった日から10日以内に届書を日本年金機構に提出しなければならない。", "correct": false, "exp": "設問の届書は、当該事実があった日から「5日以内」に提出しなければならない。"}, {"id": 37, "section": "届出等", "q": "事業主が被保険者（船員被保険者を除く。）に賞与を支払ったときの「被保険者の賞与額の届出」は、5日以内に届け出なければならないとされている。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 38, "section": "届出等", "q": "育児休業中で厚生年金保険料が免除されている者に対して賞与が支給された場合、当該賞与に係る厚生年金保険料は免除されるため、賞与支払届を提出する必要はない。", "correct": false, "exp": "育児休業中で厚生年金保険料が免除されていることを理由に賞与支払届の提出が不要となることはない。"}, {"id": 39, "section": "届出等", "q": "適用事業所の事業主は、代理人をして処理させようとするとき及び代理人を解任したときは、事後遅滞なく、文書でその旨を日本年金機構に届け出なければならない。", "correct": false, "exp": "設問の場合には、「あらかじめ」、文書でその旨を日本年金機構に届け出なければならない。"}, {"id": 40, "section": "届出等", "q": "70歳以上の使用される者の要件に該当するに至った日の前日において適用事業所に使用されていた第1号厚生年金被保険者が、引き続き当該適用事業所に使用されることにより当該要件に該当するに至ったときは、当該者の標準報酬月額に相当する額が当該要件に該当するに至った日の前日における標準報酬月額を下回る場合に限り、届出を行うことを要しない。", "correct": false, "exp": "届出を行うことを要しないのは、「当該者の標準報酬月額に相当する額が当該要件に該当するに至った日の前日における標準報酬月額と同額である場合に限り」とされている。"}, {"id": 41, "section": "届出等", "q": "第1号厚生年金被保険者に係る事業主は、その厚生年金保険に関する書類を、その完結の日から2年間、保存しなければならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 42, "section": "届出等", "q": "被保険者又は70歳以上の使用される者が、同時に2以上の事業所に使用されるに至ったときの「2以上の事業所勤務の届出」は、5日以内に届け出なければならないとされている。", "correct": false, "exp": "設問の「2以上の事業所勤務の届出」は、同時に2以上の事業所に使用されるに至った日から「10日以内」に届け出なければならない。"}, {"id": 43, "section": "届出等", "q": "老齢厚生年金の受給権者の属する世帯の世帯主その他その世帯に属する者は、当該受給権者の所在が3か月以上明らかでないときは、速やかに、所定の事項を記載した届書を日本年金機構に提出しなければならないとされている。", "correct": false, "exp": "老齢厚生年金の受給権者の属する世帯の世帯主その他その世帯に属する者は、当該受給権者の所在が「1月以上」明らかでないときは、速やかに、所定の事項を記載した届書を日本年金機構に提出しなければならない。"}, {"id": 44, "section": "届出等", "q": "老齢厚生年金の受給権者（一定の者を除く。）は、その住所を変更したときは、5日以内に、一定の事項を記載した届書を、日本年金機構に提出しなければならない。", "correct": false, "exp": "設問の場合には、「10日以内」に、一定の事項を記載した届書を、日本年金機構に提出しなければならない。"}, {"id": 45, "section": "届出等", "q": "老齢厚生年金の受給権者は、加給年金額の対象者である配偶者が65歳に達したとき、子が18歳に達した日以後の最初の3月31日が終了したとき又は子が20歳に達したときは、10日以内に必要事項を記載した届書を日本年金機構に提出しなければならない。", "correct": false, "exp": "加給年金額の対象者が一定の年齢に達したことによってその対象者に該当しなくなったときは、設問の届書を提出する必要はない。"}, {"id": 46, "section": "届出等", "q": "実施機関は、被保険者に関する原簿を備え、これに被保険者の氏名、資格の取得及び喪失の年月日、標準報酬（標準報酬月額及び標準賞与額をいう。）、基礎年金番号その他主務省令で定める事項を記録しなければならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 47, "section": "届出等", "q": "第1号厚生年金被保険者であり、又はあった者が死亡した場合においては、遺族厚生年金を受けることができる遺族は、厚生年金保険原簿に記録された特定厚生年金保険原簿記録が事実でない、又は記録されていないと思料するときは、厚生労働大臣に対し、厚生年金保険原簿の訂正の請求をすることができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 48, "section": "届出等", "q": "実施機関は、厚生年金保険制度に対する国民の理解を増進させ、及びその信頼を向上させるため、主務省令で定めるところにより、被保険者に対し、当該被保険者の保険料納付の実績及び将来の給付に関する必要な情報を分かりやすい形で通知するものとする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 49, "section": "国庫負担・標準報酬等", "q": "国庫は、毎年度、厚生年金保険事業の事務の執行（厚生労働大臣以外の実施機関によるものを除く。）に要する費用の2分の1を負担する。", "correct": false, "exp": "国庫は、毎年度、予算の範囲内で、設問の費用を負担するとされており、負担割合については特段規定されていない。"}, {"id": 50, "section": "国庫負担・標準報酬等", "q": "報酬とは、賃金、給料、俸給、手当、賞与その他いかなる名称であるかを問わず、労働者が、労働の対償として受けるすべてのものをいう。ただし、臨時に受けるもの及び3か月を超える期間ごとに受けるものは、この限りでない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 51, "section": "国庫負担・標準報酬等", "q": "「70歳以上の使用される者」に係る標準報酬月額に相当する額については、被保険者に係る標準報酬月額と同様に、標準報酬月額等級の第1級の88,000円から第32級の650,000円までの区分により定められる。", "correct": true, "exp": "設問の通り正しい。「70歳以上の使用される者」に係る標準報酬月額の等級区分は、被保険者に係る標準報酬月額の等級区分と同様である。"}, {"id": 52, "section": "国庫負担・標準報酬等", "q": "毎年3月31日における全被保険者の標準報酬月額を平均した額が標準報酬月額等級の最高等級の標準報酬月額を超える場合において、その状態が継続すると認められるときは、その翌年の4月1日から、政令で、当該最高等級の上に更に等級を加える標準報酬月額の等級区分の改定を行わなければならない。", "correct": false, "exp": "毎年3月31日における全被保険者の標準報酬月額を「平均した額の100分の200に相当する額」が標準報酬月額等級の最高等級の標準報酬月額を超える場合において、その状態が継続すると認められるときは、「その年の9月1日」から、政令で、改定を「行うことができる」。"}, {"id": 53, "section": "国庫負担・標準報酬等", "q": "実施機関は、毎年4月から6月までを算定基礎としてその年9月から翌年8月までの標準報酬月額を決定するが、6月1日から12月31日までの間に初めて被保険者資格を得た者については、資格取得時に決定された額をもって翌年8月までの各月の標準報酬月額とする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 54, "section": "国庫負担・標準報酬等", "q": "実施機関は、被保険者の資格を取得した者について、日、時間、出来高又は請負によって報酬が定められる場合には、被保険者の資格を取得した月前1か月間に当該事業所で同様の業務に従事し、かつ、同様の報酬を受ける者が受けた報酬の額を平均した額を報酬月額として、その者の標準報酬月額を決定する。", "correct": true, "exp": "設問の通り正しい。資格取得時決定に関する問題である。"}, {"id": 55, "section": "国庫負担・標準報酬等", "q": "実施機関は、被保険者が現に使用される事業所において継続した3か月間（各月とも、報酬支払の基礎となった日数が、17日以上であるものとする。）に受けた報酬の総額を3で除して得た額が、その者の標準報酬月額の基礎となった報酬月額に比べて、著しく高低を生じた場合において、必要があると認めるときは、その額を報酬月額として、その著しく高低を生じた月の翌月から、標準報酬月額を改定することができる。", "correct": true, "exp": "設問の通り正しい。随時改定に関する問題である。"}, {"id": 56, "section": "国庫負担・標準報酬等", "q": "育児休業等を終了した際に改定された標準報酬月額は、育児休業等終了日の翌日から起算して2か月を経過した日の属する月からその年の8月（当該月が7月から12月までのいずれかの月である場合は、翌年の8月）までの各月の標準報酬月額とする。", "correct": false, "exp": "いわゆる育児休業等終了時改定によって改定された標準報酬月額は、育児休業等終了日の翌日から起算して2か月を経過した日の属する月の「翌月」からその年の8月（当該翌月が7月から12月までのいずれかの月である場合は、翌年の8月）までの各月の標準報酬月額とする。"}, {"id": 57, "section": "国庫負担・標準報酬等", "q": "実施機関は、被保険者が賞与を受けた月において、その月に当該被保険者が受けた賞与額に基づき、これに1,000円未満の端数を生じたときはこれを切り捨てて、その月における標準賞与額を決定する。この場合において、当該標準賞与額が150万円を超えるときは、これを150万円とする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 58, "section": "国庫負担・標準報酬等", "q": "同時に2か所の適用事業所A及びBに使用される第1号厚生年金被保険者について、同一の月に適用事業所Aから200万円、適用事業所Bから100万円の賞与が支給された。この場合、適用事業所Aに係る標準賞与額は150万円、適用事業所Bに係る標準賞与額は100万円として決定され、この合計である250万円が当該被保険者の当該月における標準賞与額とされる。", "correct": false, "exp": "設問の場合、AとBの賞与の合算額300万円に基づき標準賞与額が決定される。合算額は300万円であり、上限額の150万円を超えるため、「150万円」が当該被保険者の標準賞与額とされる。"}, {"id": 59, "section": "保険料等", "q": "令和7年4月30日に適用事業所に使用され、令和7年5月31日に当該適用事業所に使用されなくなった厚生年金保険の被保険者の保険料は、4月分と5月分の2か月分が徴収される。", "correct": true, "exp": "設問の通り正しい。設問の場合には、資格喪失月は6月となり、保険料は、4月分と5月分の2か月分が徴収される。"}, {"id": 60, "section": "保険料等", "q": "標準報酬月額及び標準賞与額に乗じる保険料率は、それぞれ異なる率である。", "correct": false, "exp": "標準報酬月額及び標準賞与額に乗じる保険料率は、同じ率である。"}, {"id": 61, "section": "保険料等", "q": "被保険者及び被保険者を使用する事業主は、それぞれ厚生年金保険料の半額を負担するが、事業主は自らの負担すべき保険料額の負担の割合を増加することができる。", "correct": false, "exp": "事業主は自らの負担すべき保険料額の負担の割合を増加することはできない。なお、被保険者が負担すべき保険料額の負担の割合を増加することもできない。"}, {"id": 62, "section": "保険料等", "q": "第1号厚生年金被保険者が同時に2以上の適用事業所（船舶を除く。）に使用される場合における各事業主の負担すべき標準報酬月額に係る保険料の額は、各事業所について算定した報酬月額に相当する額を当該被保険者の報酬月額で除し、それにより得た数を当該被保険者の保険料の半額に乗じた額とする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 63, "section": "保険料等", "q": "第1号厚生年金被保険者が同時に2以上の適用事業所（第1号厚生年金被保険者に係るものに限る。）に使用される場合において、2以上の事業所のうち一つが船舶であるときは、船舶所有者が被保険者に係る保険料の半額を負担しかつ当該保険料及び当該被保険者の負担する保険料を納付する義務を負い、船舶以外の事業主は保険料を負担せず、納付義務も生じない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 64, "section": "保険料等", "q": "第1子に係る育児休業期間中の保険料の徴収の特例の適用を受けている第1号厚生年金被保険者が、新たに第2子に係る産前産後休業期間中の保険料の徴収の特例の適用を受ける産前産後休業を開始したときは、当該育児休業期間中の保険料の徴収の特例の適用を受けることができなくなる。", "correct": true, "exp": "設問の通り正しい。産前産後休業期間中の保険料の徴収の特例の適用を受ける被保険者は、育児休業期間中の保険料の徴収の特例の対象とされない。"}, {"id": 65, "section": "保険料等", "q": "育児休業期間中の第1号厚生年金被保険者に係る保険料の免除の規定については、任意単独被保険者は対象になるが、高齢任意加入被保険者はその対象にはならない。", "correct": false, "exp": "任意単独被保険者及び高齢任意加入被保険者は、いずれも育児休業期間中の第1号厚生年金被保険者に係る保険料の免除の規定の対象となる。"}, {"id": 66, "section": "保険料等", "q": "産前産後休業をしている被保険者に係る保険料については、事業主負担分及び被保険者負担分の両方が免除される。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 67, "section": "保険料等", "q": "産前産後休業期間中の保険料の免除の始期は産前産後休業を開始した日の属する月の翌月で、終期はその産前産後休業が終了する日の翌日が属する月である。", "correct": false, "exp": "産前産後休業期間中の保険料の免除の始期は産前産後休業を開始した日の属する月で、終期はその産前産後休業が終了する日の翌日が属する月の前月である。"}, {"id": 68, "section": "保険料等", "q": "毎月の保険料は、翌月末日までに、納付しなければならない。", "correct": true, "exp": "設問の通り正しい。なお、任意単独被保険者及び高齢任意加入被保険者に係る保険料の納期限についても、翌月末日とされている。"}, {"id": 69, "section": "保険料等", "q": "厚生労働大臣は、納付義務者から、預金又は貯金の払出しとその払い出した金銭による保険料の納付をその預金口座又は貯金口座のある金融機関に委託して行うことを希望する旨の申出があった場合には、その納付が確実と認められ、かつ、その申出を承認することが保険料の徴収上有利と認められるときに限り、その申出を承認することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 70, "section": "保険料等", "q": "厚生労働大臣は、納入の告知をした保険料額が当該納付義務者が納付すべき保険料額を超えていることを知ったときは、その超えている部分に関する納入の告知を、その納入の告知の日の翌日から1年以内の期日に納付されるべき保険料について納期を繰り上げてしたものとみなすことができる。", "correct": false, "exp": "設問の場合、納入の告知の日の翌日から「6か月」以内の期日に納付されるべき保険料について納期を繰り上げてしたものとみなすことができる。"}, {"id": 71, "section": "保険料等", "q": "第1号厚生年金被保険者に係る事業主は、被保険者に対して通貨をもって報酬を支払う場合においては、厚生労働大臣に申出を行い、その承認を得て、被保険者の負担すべき前月の標準報酬月額に係る保険料を報酬から控除することができる。", "correct": false, "exp": "保険料の源泉控除をするに当たり、厚生労働大臣への申出及びその承認を得ることを要しない。"}, {"id": 72, "section": "保険料等", "q": "保険料は、納付義務者が、国税、地方税その他の公課の滞納によって、滞納処分を受けるときは、納期前であっても、すべて徴収することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 73, "section": "保険料等", "q": "保険料等の督促状により指定する期限は、督促状を発する日から起算して10日以上を経過した日でなければならない。ただし、保険料の繰上徴収が認められる要件に該当する場合は、この限りでない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 74, "section": "保険料等", "q": "厚生労働大臣は、督促を受けた納付義務者が指定の期限までに保険料等を納付しないとき、国税滞納処分の例によってこれを処分し、又は納付義務者の居住地若しくはその者の財産所在地の市町村に対して、その処分を請求することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 75, "section": "保険料等", "q": "日本年金機構は、滞納処分等を行う場合には、あらかじめ、厚生労働大臣の認可を受けるとともに、滞納処分等実施規程に従い、徴収職員に行わせなければならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 76, "section": "保険料等", "q": "厚生労働大臣は、日本年金機構の求めに応じ滞納処分等の権限の全部又は一部を自らが行うこととした場合における滞納処分等に係る納付義務者が滞納処分等の執行を免れる目的でその財産について隠ぺいしているおそれがあることその他の政令で定める事情があるため保険料等の効果的な徴収を行う上で必要があると認めるときは、財務大臣に、当該納付義務者に関する情報その他必要な情報を提供するとともに、当該納付義務者に係る滞納処分等その他の処分の権限の全部又は一部を委任することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 77, "section": "保険料等", "q": "第1号厚生年金被保険者に係る保険料の納付義務者の住所及び居所がともに明らかでないため、公示送達の方法によって滞納された保険料の督促が行われた場合にも、保険料額に所定の割合を乗じて計算した延滞金が徴収される。", "correct": false, "exp": "公示送達の方法によって滞納保険料の督促が行われた場合には、延滞金は徴収されない。"}, {"id": 78, "section": "保険料等", "q": "保険料に係る延滞金は、保険料額が1,000円未満であるときは徴収しない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 79, "section": "保険料等", "q": "保険料その他厚生年金保険法の規定による徴収金の先取特権の順位は、国税及び地方税に次ぐものとする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 80, "section": "保険給付", "q": "厚生年金保険法による保険給付は、老齢厚生年金、障害厚生年金、障害手当金、遺族厚生年金、脱退一時金の5種類である。", "correct": false, "exp": "厚生年金保険法による保険給付は5種類ではない。本則で定める保険給付として、老齢厚生年金、障害厚生年金、障害手当金及び遺族厚生年金があり、また、附則で定める保険給付として、脱退一時金、脱退手当金、特例老齢年金及び特例遺族年金がある。"}, {"id": 81, "section": "保険給付", "q": "保険給付を受ける権利は、その権利を有する者の請求に基づいて、地方厚生局長が裁定する。", "correct": false, "exp": "保険給付を受ける権利は、その権利を有する者の請求に基づいて、「実施機関」が裁定する。"}, {"id": 82, "section": "保険給付", "q": "60歳台前半の老齢厚生年金の受給権者が65歳に達し、65歳からの老齢厚生年金の裁定を受けようとする場合は、新たに裁定請求書を提出する必要はない。", "correct": false, "exp": "設問の場合、新たに裁定請求書（年金請求書）を提出しなければならない。"}, {"id": 83, "section": "保険給付", "q": "保険給付の額に端数が生じたときには、5円未満の端数は切り捨て、5円以上10円未満の端数は10円に切り上げる。", "correct": false, "exp": "保険給付の額に「50銭未満」の端数が生じたときは、これを切り捨て、「50銭以上1円未満」の端数が生じたときは、これを「1円」に切り上げる。"}, {"id": 84, "section": "保険給付", "q": "年金の支給は、年金を支給すべき事由が生じた月の翌月から始め、また、その支給を停止すべき事由が生じたときは、その事由が生じた月から支給しない。", "correct": false, "exp": "年金は、その支給を停止すべき事由が生じたときは、その事由が生じた月の翌月から（その事由が消滅した月までの間）、支給しない。"}, {"id": 85, "section": "保険給付", "q": "年金は、毎年2月、4月、6月、8月、10月及び12月の6期に、それぞれその前月分までを支払う。ただし、前支払期月に支払うべきであった年金又は権利が消滅した場合若しくは年金の支給を停止した場合におけるその期の年金は、支払期月でない月であっても、支払うものとする。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 86, "section": "保険給付", "q": "毎支払期月における年金の支払額に1円未満の端数が生じたときは、これを切り捨てるものとし、毎年4月から翌年3月までの間においてこれにより切り捨てた金額の合計額については、これを翌年度の4月の支払期月の年金額に加算するものとする。", "correct": false, "exp": "毎支払期月における年金の支払額に1円未満の端数が生じたときは、これを切り捨てるものとし、「毎年3月から翌年2月まで」の間において切り捨てた金額の合計額については、これを「当該2月」の支払期月の年金額に加算するものとする。"}, {"id": 87, "section": "老齢厚生年金", "q": "保険料納付済期間と保険料免除期間とを合算した期間を10年以上有する者が65歳に達した場合であっても、厚生年金保険の被保険者期間を1年以上有していないときは、その者に老齢厚生年金は支給されない。", "correct": false, "exp": "設問の場合、厚生年金保険の被保険者期間を「1月以上」有していれば、老齢厚生年金は支給される。"}, {"id": 88, "section": "老齢厚生年金", "q": "2以上の種別の被保険者であった期間を有する者の老齢厚生年金の額の計算においては、その者の2以上の被保険者の種別に係る期間を合算して1の期間に係る被保険者期間のみを有するものとみなして平均標準報酬額を算出する。", "correct": false, "exp": "2以上の種別の被保険者であった期間を有する者に係る老齢厚生年金の額の計算においては、その者の2以上の被保険者の種別に係る被保険者期間ごとに平均標準報酬額を算出する。"}, {"id": 89, "section": "老齢厚生年金", "q": "受給権者が毎年9月1日（以下本肢において「基準日」という。）において被保険者である場合（基準日に被保険者の資格を取得した場合を除く。）の老齢厚生年金の額は、基準日の属する月前の被保険者であった期間をその計算の基礎とするものとし、基準日の属する月から、年金の額を改定する。", "correct": false, "exp": "設問の場合、基準日の属する月の翌月から、年金の額を改定する。"}, {"id": 90, "section": "老齢厚生年金", "q": "被保険者である老齢厚生年金の受給権者が事業所に使用されなくなったことによりその被保険者の資格を喪失し、かつ、被保険者となることなくして被保険者の資格を喪失した日から起算して1月を経過したときは、その事業所に使用されなくなった日から起算して1月を経過した日の属する月から、年金額が改定される。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 91, "section": "老齢厚生年金", "q": "被保険者である老齢厚生年金の受給者（昭和30年7月1日生まれ）が70歳になり当該被保険者の資格を喪失した場合における老齢厚生年金は、令和7年8月分から年金の額が改定される。", "correct": false, "exp": "設問の場合、資格喪失日である令和7年6月30日（70歳到達日）から起算して1月を経過した日が属する月である令和7年7月分から年金額が改定される。"}, {"id": 92, "section": "老齢厚生年金", "q": "60歳台前半の老齢厚生年金の定額部分と昭和36年4月1日以後の20歳以上65歳未満の厚生年金保険の被保険者期間に係る老齢基礎年金相当額に差があるときは、当該差額を老齢基礎年金に経過的に加算する。", "correct": false, "exp": "60歳台前半の老齢厚生年金の定額部分の額が昭和36年4月1日以後の20歳以上「60歳」未満の厚生年金保険の被保険者期間に係る老齢基礎年金相当額を超えるときは、その差額（経過的加算額）を65歳以後の老齢厚生年金に加算する。"}, {"id": 93, "section": "加給年金額", "q": "年金の額の計算の基礎となる被保険者期間の月数が240以上である老齢厚生年金に加算される加給年金額の対象となる子の年齢要件については、当該子が障害等級1級又は2級に該当する障害の状態にないときは、18歳に達する日以後の最初の3月31日までの間、及び当該子が障害等級1級又は2級に該当する障害の状態にあるときは20歳未満である。", "correct": true, "exp": "設問の通り正しい。なお、加給年金額の対象となる配偶者の年齢要件については、65歳未満とされている。"}, {"id": 94, "section": "加給年金額", "q": "老齢厚生年金の受給権者について、受給権を取得した当時、生計を維持していた子が19歳に達した後初めて障害等級1級または2級に該当する障害の状態になった場合には、当該子が20歳に達するまでの間、加給年金額が加算される。", "correct": false, "exp": "加給年金額の対象者である子について、18歳に達する日以後の最初の3月31日が終了したときは、加給年金額の加算は終了する。その後、その子が「19歳に達した後初めて障害等級1級または2級に該当する障害の状態になった場合」であっても、再度加給年金額が加算されることはない。"}, {"id": 95, "section": "加給年金額", "q": "老齢厚生年金の加給年金額の加算の対象となる子（3人）がある場合の加給年金額は、1人目及び2人目の子については224,700円に、3人目の子については74,900円に、それぞれ改定率を乗じて得た額に端数処理をして得た額である。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 96, "section": "加給年金額", "q": "昭和9年4月2日以降に生まれた老齢厚生年金の受給権者に支給される配偶者の加給年金額に加算される特別加算の額は、昭和16年4月2日生まれの受給権者よりも昭和18年4月2日生まれの受給権者の方が高額になる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 97, "section": "加給年金額", "q": "老齢厚生年金（被保険者期間の月数が240以上であるものとする。）の受給権者がその権利を取得した当時胎児であった子が出生したときは、その権利を取得した月の翌月に遡って、加給年金額を加算した年金額に改定する。", "correct": false, "exp": "設問の場合、「胎児の出生」の月の翌月から、年金の額を改定する。"}, {"id": 98, "section": "加給年金額", "q": "老齢厚生年金に加算される加給年金額の対象となる配偶者（昭和35年4月2日生まれ）が受給資格期間を満たさないため老齢基礎年金を受給できない場合には、当該配偶者が65歳に達した日の属する月の翌月以後も引き続き加給年金額が加算される。", "correct": false, "exp": "設問の配偶者が65歳に達したときは、当該配偶者を対象とする加給年金額は加算しないものとし、当該配偶者が65歳に達した日の属する月の翌月から老齢厚生年金の額が改定される。"}, {"id": 99, "section": "加給年金額", "q": "子に係る加給年金額が加算された老齢厚生年金について、その加給年金額の対象者である子が養子縁組によって当該老齢厚生年金の受給権者の配偶者の養子になったときは、その翌月から当該子に係る加給年金額は加算されないこととなる。", "correct": false, "exp": "加給年金額の対象者である子が養子縁組によって当該老齢厚生年金の受給権者の「配偶者以外の者」の養子となったときは、その翌月から当該子に係る加給年金額は加算されないこととなる。"}, {"id": 100, "section": "加給年金額", "q": "老齢厚生年金の加給年金については、加算が行われている配偶者が、その額の計算の基礎となる被保険者期間の月数が240か月以上である老齢厚生年金の支給を受けることができるときは、その間、当該配偶者について加算する額に相当する部分の支給を停止する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 101, "section": "加給年金額", "q": "老齢厚生年金に加算される加給年金額の対象となる配偶者が障害等級3級の障害厚生年金を受給している場合であっても、加給年金額は支給停止されない。", "correct": false, "exp": "配偶者を対象とする加給年金額は、当該配偶者が障害厚生年金の支給を受けることができるときは、それが障害等級3級の障害厚生年金であっても、支給停止される。"}, {"id": 102, "section": "在職老齢年金（高在老）", "q": "老齢厚生年金を受給している被保険者であって適用事業所に使用される者が70歳に到達したときは、その日に被保険者の資格を喪失し、当該喪失日が属する月以後の保険料を納めることはないが、一定の要件に該当する場合は、老齢厚生年金の一部又は全部が支給停止される。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 103, "section": "在職老齢年金（高在老）", "q": "老齢厚生年金の受給権者が被保険者である日が属する月の在職老齢年金の支給停止額を計算する際に用いる総報酬月額相当額とは、当該受給権者に係る過去1年間の各月の標準報酬月額の総額を12で除して得た額である。", "correct": false, "exp": "被保険者である受給権者に係る総報酬月額相当額とは、「当該受給権者の標準報酬月額とその月（被保険者である日が属する月）以前の1年間の標準賞与額の総額を12で除して得た額とを合算して得た額」である。"}, {"id": 104, "section": "在職老齢年金（高在老）", "q": "60歳台後半の在職老齢年金の仕組みにおいて、経過的加算額及び繰下げ加算額は、支給停止される額の計算に用いる基本月額の計算の対象に含まれる。", "correct": false, "exp": "経過的加算額及び繰下げ加算額は、基本月額の計算の対象に含まれない。"}, {"id": 105, "section": "在職老齢年金（高在老）", "q": "60歳台後半の老齢厚生年金の受給権者が被保険者である間、老齢厚生年金については、1か月当たり、原則として、総報酬月額相当額と基本月額の合計額から支給停止調整額を控除した額の2分の1に相当する額が支給停止される。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 106, "section": "在職老齢年金（高在老）", "q": "60歳台後半の老齢厚生年金の受給権者が被保険者である間の総報酬月額相当額が400,000円であって、基本月額が125,000円の場合における支給停止基準額は、22,500円に12を乗じて得た額である。", "correct": false, "exp": "設問の場合における支給停止基準額は、「12,500円」に12を乗じて得た額である。（400,000円＋125,000円−500,000円）×1/2＝12,500円"}, {"id": 107, "section": "在職老齢年金（高在老）", "q": "60歳台後半の在職老齢年金制度においては、老齢基礎年金は、支給停止されず全額支給される。", "correct": true, "exp": "設問の通り正しい。老齢基礎年金は在職老齢年金の仕組みによる支給停止の対象とされていない。"}, {"id": 108, "section": "在職老齢年金（高在老）", "q": "在職老齢年金を受給する者の総報酬月額相当額が改定された場合は、改定が行われた月の翌月から、新たな総報酬月額相当額に基づいて支給停止額が再計算される。", "correct": false, "exp": "総報酬月額相当額が改定された場合は、「改定が行われた月」から、新たな総報酬月額相当額に基づいて支給停止額が再計算される。"}, {"id": 109, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "昭和36年4月2日以降に生まれた60歳以上の男子（船員又は坑内員であった期間を有する者、特定警察職員等である者を除く。）であって、老齢厚生年金の受給資格期間を満たしているものが、1月以上の厚生年金保険の被保険者期間を有し、かつ、厚生年金保険の任意加入被保険者でないときは、65歳に達する前に、実施機関に老齢厚生年金の支給繰上げの請求をすることができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 110, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "老齢厚生年金の支給繰上げの請求は、老齢基礎年金の支給繰上げの請求と同時に行う必要はない。", "correct": false, "exp": "老齢厚生年金の支給繰上げの請求は、老齢基礎年金の支給繰上げの請求を行うことができる者にあっては、その請求と同時に行わなければならない。"}, {"id": 111, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "老齢厚生年金の支給を繰上げて受給している者が、当該老齢厚生年金の受給権を取得した日以後65歳に達する目前に被保険者期間を有した場合には、その者が65歳に達した日の属する月の翌月から年金額の改定が行われる。", "correct": true, "exp": "設問の通り正しい。設問の繰上げ支給の老齢厚生年金の受給権者については、65歳に達するまでの間は、在職定時改定は行われず、また、退職した場合であっても退職改定は行われない。65歳に達したときに、その翌月から年金額の改定が行われることとなる。"}, {"id": 112, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "老齢厚生年金の受給権を有する者であってその受給権を取得した日から起算して1年を経過した目前に当該老齢厚生年金を請求していなかったものであっても、その者が当該老齢厚生年金の受給権を取得したときに、遺族厚生年金の受給権者であった場合には、当該老齢厚生年金の支給繰下げの申出をすることはできない。", "correct": true, "exp": "設問の通り正しい。老齢厚生年金の受給権を取得したときに、①他の年金たる保険給付又は②厚生年金保険法による年金たる給付（老齢基礎年金及び付加年金並びに障害基礎年金を除く。）の受給権者であった場合には、当該老齢厚生年金の支給繰下げの申出をすることはできない。"}, {"id": 113, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "老齢厚生年金の支給繰下げの申出は、老齢基礎年金の支給繰下げの申出と同時に行わなければならない。", "correct": false, "exp": "老齢厚生年金の支給繰下げの申出は、老齢基礎年金の支給繰下げの申出と同時に行う必要はない。"}, {"id": 114, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "60歳台前半の老齢厚生年金の受給権者であった者は、老齢厚生年金の支給繰下げの申出を行うことはできない。", "correct": false, "exp": "60歳台前半の老齢厚生年金の受給権者であった者であっても、所定の要件を満たしていれば、老齢厚生年金の支給繰下げの申出を行うことはできる。"}, {"id": 115, "section": "老齢厚生年金の支給繰上げ・繰下げ", "q": "70歳に達した者であって、その者が老齢厚生年金の支給繰下げの申出を行った場合に支給する老齢厚生年金の額に加算する額は、繰下げ対象額（在職老齢年金の仕組みにより支給停止があったと仮定しても支給を受けることができた額に限られる。）から経過的加算額を控除して得られた額に増額率を乗じて得られる額である。", "correct": false, "exp": "支給繰下げの申出を行った場合に支給する老齢厚生年金の額に加算する額は、増額の算定基礎となる年金額（設問でいう繰下げ対象額）に増額率を乗じて得られる額であるが、増額の算定基礎となる年金額には経過的加算額が含まれる。"}, {"id": 116, "section": "特別支給の老齢厚生年金", "q": "昭和41年4月1日生まれの女子の第1号厚生年金被保険者期間に基づく特別支給の老齢厚生年金の支給開始年齢は、原則として64歳である。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 117, "section": "特別支給の老齢厚生年金", "q": "60歳台前半の老齢厚生年金の定額部分の額の計算に係る被保険者期間の月数は、生年月日にかかわらず、480が上限とされている。", "correct": false, "exp": "定額部分の額の計算の基礎となる被保険者期間の月数の上限は、生年月日に応じて、420から480とされている。"}, {"id": 118, "section": "特別支給の老齢厚生年金", "q": "特別支給の老齢厚生年金の報酬比例部分の額の計算に係る被保険者期間の月数には、定額部分と同様の上限が設けられている。", "correct": false, "exp": "報酬比例部分の額の計算に係る被保険者期間の月数には、上限は設けられていない。"}, {"id": 119, "section": "特別支給の老齢厚生年金", "q": "報酬比例部分のみの特別支給の老齢厚生年金の受給権者となった日において、被保険者でなく、かつ、障害等級3級の障害厚生年金を受けることができた者が、その後、老齢厚生年金の額の計算に係る特例（いわゆる障害者の特例）の適用を請求した場合には、当該老齢厚生年金の受給権者となった日に当該請求があったものとみなされる。", "correct": true, "exp": "設問の通り正しい。設問の者が、いわゆる障害者の特例の適用を請求した場合においては、設問の老齢厚生年金の受給権者となった日に当該請求があったものとみなされ、当該老齢厚生年金の受給権者となった日の属する月の翌月にさかのぼって報酬比例部分と定額部分とを合わせた額に年金額が改定される。"}, {"id": 120, "section": "特別支給の老齢厚生年金", "q": "60歳台前半の第1号厚生年金被保険者期間に基づく老齢厚生年金の受給権者（昭和29年4月2日から昭和41年4月1日までの間に生まれた女子とする。）が、その権利を取得した当時、被保険者でなく、かつ、その者の被保険者期間が44年以上であるときは、当該老齢厚生年金の額は、報酬比例部分の年金額に加給年金額が加算されるが、定額部分の年金額は支給されない。", "correct": false, "exp": "設問の女子は、いわゆる長期加入者の特例に該当するため、60歳台前半の老齢厚生年金の支給開始年齢に達したときから定額部分と報酬比例部分とを合わせた額の老齢厚生年金が支給され、また、加給年金額対象者があるときは、加給年金額も加算される。"}, {"id": 121, "section": "特別支給の老齢厚生年金", "q": "昭和33年4月10日生まれの男性は、第1号厚生年金被保険者として4年、第2号厚生年金被保険者として40年加入してきた。当該男性は、厚生年金保険の被保険者でなければ、63歳から定額部分と報酬比例部分の特別支給の老齢厚生年金が支給される。", "correct": false, "exp": "2以上の種別の被保険者であった期間を有する者に係る老齢厚生年金について、いわゆる長期加入者の特例の要件である「被保険者期間が44年以上であること」の判定に当たっては、2以上の種別の被保険者であった期間に係る被保険者期間を合算せず、各号の厚生年金被保険者期間ごとに行う。"}, {"id": 122, "section": "特別支給の老齢厚生年金の支給停止等", "q": "60歳台前半の老齢厚生年金の基本月額が170,000円であり、その者の総報酬月額相当額が360,000円の場合の在職老齢年金の支給停止額は15,000円となる。なお、この基本月額には加給年金額が加算されている老齢厚生年金の場合、加給年金額を含めたものである。", "correct": false, "exp": "基本月額は、加給年金額が加算されている老齢厚生年金の場合、加給年金額を除いた額を12で除して得た額である。"}, {"id": 123, "section": "特別支給の老齢厚生年金の支給停止等", "q": "特別支給の老齢厚生年金（基本月額200,000円）を受給する被保険者について、総報酬月額相当額が320,000円であったとき、支給停止後の年金月額は10,000円となる。", "correct": false, "exp": "設問の支給停止後の年金月額は、「190,000円」となる。支給停止月額＝（320,000円＋200,000円−500,000円）×1/2＝10,000円、支給停止後の年金月額＝200,000円−10,000円＝190,000円"}, {"id": 124, "section": "特別支給の老齢厚生年金の支給停止等", "q": "60歳台前半の老齢厚生年金の受給権者が雇用保険法の規定による求職の申込みをしたときは、基本手当に係る調整対象期間について、当該老齢厚生年金の報酬比例部分相当額のみ支給停止し、定額部分相当額は支給停止しない。", "correct": false, "exp": "設問の場合、定額部分相当額を含めた老齢厚生年金の全額を支給停止する。"}, {"id": 125, "section": "特別支給の老齢厚生年金の支給停止等", "q": "加給年金額が加算された60歳台前半の老齢厚生年金が、雇用保険の基本手当との調整により支給停止される場合であっても、加給年金額については支給停止されない。", "correct": false, "exp": "基本手当との調整により60歳台前半の老齢厚生年金が支給停止される場合は、加給年金額についても支給停止される。"}, {"id": 126, "section": "特別支給の老齢厚生年金の支給停止等", "q": "60歳台前半の老齢厚生年金と障害厚生年金の受給権を有する者が、障害厚生年金を選択受給している場合において、この者が、雇用保険法の規定による求職の申込みをしたときは、当該障害厚生年金は、基本手当との調整対象となり、支給停止する。", "correct": false, "exp": "障害厚生年金は、基本手当との調整対象とならない。基本手当との調整対象となるのは、65歳未満の者に支給する老齢厚生年金に限る。"}, {"id": 127, "section": "特別支給の老齢厚生年金の支給停止等", "q": "調整対象期間中に基本手当の支給を受けた日とみなされる日及びこれに準ずる日として政令で定める日が1日もない月があった場合でも、その月について老齢厚生年金の支給が停止される。", "correct": false, "exp": "基本手当の支給を受けた日とみなされる日及びこれに準ずる日として政令で定める日が1日もない月があった場合には、その月の分の老齢厚生年金については、基本手当との調整は行われず、その支給は停止されない。"}, {"id": 128, "section": "特別支給の老齢厚生年金の支給停止等", "q": "雇用保険の基本手当との調整により老齢厚生年金の支給が停止された者について、当該老齢厚生年金に係る調整対象期間が終了するに至った場合、調整対象期間の各月のうち年金停止月の数から基本手当の支給を受けた日とみなされる日の数を30で除して得た数（1未満の端数が生じたときは、これを1に切り上げるものとする。）を控除して得た数が1以上であるときは、年金停止月のうち、当該控除して得た数に相当する月数分の直近の各月については、雇用保険の基本手当との調整による老齢厚生年金の支給停止が行われなかったものとみなす。", "correct": true, "exp": "設問の通り正しい。いわゆる事後精算の仕組みについての記述である。"}, {"id": 129, "section": "特別支給の老齢厚生年金の支給停止等", "q": "60歳台前半の老齢厚生年金の受給権者であって、厚生年金保険の被保険者である日が属する月について60歳台前半の在職老齢年金の支給調整の仕組みが適用されている者について、その者が雇用保険法の規定による高年齢雇用継続基本給付金の支給を受けることができるときは、高年齢雇用継続基本給付金が支給停止される。", "correct": false, "exp": "設問の場合に支給停止の対象とされるのは、高年齢雇用継続基本給付金ではなく、老齢厚生年金である。"}, {"id": 130, "section": "特別支給の老齢厚生年金の支給停止等", "q": "被保険者期間を1年以上有する昭和36年4月1日生まれの男性が老齢厚生年金の支給繰上げの請求をした場合、その者に支給する老齢厚生年金の額の計算に用いる減額率は、請求日の属する月から64歳に達する日の属する月の前月までの月数に一定率を乗じて得た率である。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 131, "section": "特別支給の老齢厚生年金の支給停止等", "q": "特別支給の老齢厚生年金の受給権は、受給権者が死亡したときにのみ消滅する。", "correct": false, "exp": "特別支給の老齢厚生年金の受給権は、受給権者が死亡したときに消滅するほか、受給権者が65歳に達したときにも消滅する。"}, {"id": 132, "section": "障害厚生年金の支給要件等", "q": "厚生年金保険の被保険者であった者が退職し、厚生年金保険の第1号被保険者となっていたが、その後再就職したことにより再び厚生年金保険の被保険者となった。厚生年金保険の第1号被保険者であった時期に初診日があり、再び厚生年金保険の被保険者となってから3級の障害認定を受けた場合、保険料納付要件を満たしていれば障害厚生年金は支給される。", "correct": false, "exp": "障害厚生年金が支給されるためには、初診日において厚生年金保険の被保険者であることが必要である。"}, {"id": 133, "section": "障害厚生年金の支給要件等", "q": "厚生年金保険法第47条に定める障害認定日は、初診日から起算して1年6か月を経過した日又は当該障害の原因となった傷病が治った日（その症状が固定し、治療の効果が期待できない状態に至った日を含む。）のいずれか早い方である。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 134, "section": "障害厚生年金の支給要件等", "q": "傷病の初診日において65歳未満の被保険者であり、障害認定日において障害等級の1級、2級又は3級に該当する程度の障害の状態にあり、かつ保険料納付要件を満たしているときは、当該障害に係る障害認定日が65歳に達する目前までになくても、障害厚生年金を支給する。", "correct": true, "exp": "設問の通り正しい。障害認定日が65歳に達する目前にあることは、一般的な障害厚生年金の要件とされていない。したがって、障害認定日が65歳に達した日以後であっても、所定の支給要件を満たしているときは、障害厚生年金が支給される。"}, {"id": 135, "section": "障害厚生年金の支給要件等", "q": "厚生年金保険の被保険者であった18歳のときに初診日のある傷病について、その障害認定日において障害等級3級の障害の状態にある場合にその者が20歳未満のときは、障害厚生年金の受給権は20歳に達したときに発生する。", "correct": false, "exp": "設問の場合、障害厚生年金の受給権は、障害認定日に発生する。"}, {"id": 136, "section": "障害厚生年金の支給要件等", "q": "いわゆる事後重症による障害厚生年金について、対象となる障害の程度は障害等級1級又は2級に限られ、障害の程度が障害等級3級に該当するに至った場合には請求することができない。", "correct": false, "exp": "事後重症による障害厚生年金の対象となる障害の程度には、障害等級3級も含まれる。"}, {"id": 137, "section": "障害厚生年金の支給要件等", "q": "いわゆる基準傷病に基づく障害による障害厚生年金の支給は、その受給権を取得した月の翌月から開始される。", "correct": false, "exp": "基準傷病に基づく障害による障害厚生年金の支給は、「当該障害厚生年金の請求があった月の翌月」から始めるものとする。"}, {"id": 138, "section": "障害厚生年金の支給要件等", "q": "障害厚生年金（その権利を取得した当時から引き続き障害等級の1級又は2級に該当しない程度の障害の状態にある受給権者に係るものを除く。）の受給権者に対して更に障害厚生年金を支給すべき事由が生じたときは、前後の障害を併合した障害の程度による障害厚生年金を支給する。", "correct": true, "exp": "設問の通り正しい。なお、障害厚生年金の受給権者が設問の規定により前後の障害を併合した障害の程度による障害厚生年金の受給権を取得したときは、従前の障害厚生年金の受給権は、消滅する。"}, {"id": 139, "section": "障害厚生年金の支給要件等", "q": "障害厚生年金（その権利を取得した当時から1級又は2級に該当しないものを除く。）の受給権者が、更に障害厚生年金の受給権を取得した場合に、新たに取得した障害厚生年金が、労働基準法第77条の規定に定める障害補償を受ける権利を取得したことによりその支給を停止すべきものであるときは、その停止すべき期間、その者に対して従前の障害厚生年金を支給する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 140, "section": "障害厚生年金の額", "q": "障害の程度が障害等級の3級に該当する者に支給する障害厚生年金の額は、2級に該当する者に支給する額の100分の50に相当する額とする。", "correct": false, "exp": "障害等級の3級に該当する者に支給する障害厚生年金の額は、原則として、障害等級の2級に該当する者に支給する額と同額である。"}, {"id": 141, "section": "障害厚生年金の額", "q": "障害厚生年金の額の計算の基礎となる被保険者期間の月数が240を超えるときは、これを240とする。", "correct": false, "exp": "障害厚生年金の額の計算の基礎となる被保険者期間の月数が300に満たないときは、これを300とすることとされている。"}, {"id": 142, "section": "障害厚生年金の額", "q": "障害厚生年金の額については、当該障害厚生年金の支給事由となった障害に係る障害認定日の属する月の前月までの被保険者であった期間に限り、その計算の基礎とする。", "correct": false, "exp": "障害認定日の属する「月」までの被保険者であった期間を、障害厚生年金の額の計算の基礎とする。"}, {"id": 143, "section": "障害厚生年金の額", "q": "被保険者である障害厚生年金の受給権者が令和7年3月31日付けで退職し同年4月1日にその被保険者の資格を喪失した。その後、この者が被保険者となることなくして被保険者の資格を喪失した日から起算して1月を経過したときは、同年4月から、当該障害厚生年金の額が改定される。", "correct": false, "exp": "障害厚生年金について設問のようないわゆる老齢厚生年金の退職改定に相当する規定はなく、障害認定日の月後における被保険者であった期間が、障害厚生年金の額の計算の基礎とされることはない。"}, {"id": 144, "section": "障害厚生年金の額", "q": "障害等級3級の障害厚生年金の年金額には、配偶者についての加給年金額は加算されないが、障害基礎年金の年金額の3分の2に相当する最低保障額がある。", "correct": false, "exp": "設問の障害厚生年金の最低保障額は、障害基礎年金の額の「3分の2」ではなく「4分の3」に相当する額である。"}, {"id": 145, "section": "障害厚生年金の額", "q": "障害等級3級に該当する障害厚生年金の受給権者の障害の程度が増進し2級に改定された場合、その受給権を取得した日以後に、その者によって生計を維持している65歳未満の配偶者を有するに至ったときであっても、配偶者加給年金額は加算されない。", "correct": false, "exp": "障害厚生年金の受給権を取得後に生計を維持する65歳未満の配偶者を有するに至った場合であっても、障害等級1級又は2級に該当する者に支給する障害厚生年金には、当該配偶者を加算対象とする加給年金額が加算される。"}, {"id": 146, "section": "障害厚生年金の額", "q": "障害の程度が増進したことによる障害厚生年金の額の改定請求は、受給権者の障害の程度が増進したことが明らかである場合として厚生労働省令で定める場合を除き、当該障害厚生年金の受給権を取得した日又は実施機関の診査を受けた日から起算して1年を経過した日後でなければ行うことができない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 147, "section": "障害厚生年金の額", "q": "障害等級2級の障害厚生年金と同一の支給事由に基づく障害基礎年金の受給権者が、厚生年金保険の第1号被保険者になり、その期間中に初診日がある傷病によって厚生年金保険法第34条第4項の規定による障害基礎年金とその他障害との併合が行われ、当該障害基礎年金が障害等級1級の額に改定された場合には、障害厚生年金についても障害等級1級の額に改定される。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 148, "section": "障害厚生年金の支給停止・失権", "q": "業務上の傷病により障害等級に該当する程度の障害の状態にある場合に、当該傷病により労働基準法第77条の規定による障害補償を受ける権利を取得したときは、障害厚生年金は6年間、その支給が停止されるが、労働者災害補償保険による障害補償年金を受ける権利を取得したときは、障害厚生年金は支給停止とはならない。", "correct": true, "exp": "設問の通り正しい。障害厚生年金の受給権者が、同一の事由について労災保険法による障害補償年金を受ける権利を取得したときは、当該障害補償年金が減額調整され、障害厚生年金は支給停止とならない。"}, {"id": 149, "section": "障害厚生年金の支給停止・失権", "q": "障害厚生年金は、受給権者が障害等級に該当する程度の障害の状態に該当しなくなったときは、3年を限度に、その支給を停止する。", "correct": false, "exp": "障害厚生年金は、受給権者が障害等級に該当する程度の障害の状態に該当しなくなったときは、失権事由等に該当しない限り、その障害の状態に該当しない間、その支給を停止する。"}, {"id": 150, "section": "障害厚生年金の支給停止・失権", "q": "障害厚生年金は、受給権者が厚生年金保険の被保険者である日が属する月については、その全部又は一部の支給が停止される。", "correct": false, "exp": "障害厚生年金について、設問のような在職老齢年金にあたる規定は設けられていない。"}, {"id": 151, "section": "障害厚生年金の支給停止・失権", "q": "障害厚生年金の受給権者が厚生年金保険法第48条第1項の併合認定の規定により前後の障害を併合した障害の程度による障害厚生年金の受給権を取得したときは、従前の障害厚生年金の支給を停止する。", "correct": false, "exp": "設問の場合、従前の障害厚生年金の受給権は消滅する。"}, {"id": 152, "section": "障害厚生年金の支給停止・失権", "q": "障害厚生年金の受給権は、障害等級3級以上の障害の状態に該当しなくなり、そのまま65歳に達した日又は障害の状態に該当しなくなった日から起算してそのまま該当することなく3年経過した日のどちらか早い日に消滅する。", "correct": false, "exp": "設問の場合、どちらか「早い日」ではなく、どちらか「遅い日」に、障害厚生年金の受給権は消滅する。"}, {"id": 153, "section": "障害厚生年金の支給停止・失権", "q": "障害厚生年金の受給権者で、65歳に達する日前に障害等級に該当する程度の障害の状態に該当しなくなったために支給が停止されていた者が、66歳の時点で再度障害等級に該当する程度の障害の状態になった場合には、停止されてから3年を経過していなければ障害厚生年金の支給が開始される。", "correct": true, "exp": "設問の通り正しい。なお、再度障害等級に該当する程度の障害の状態となった66歳の時点ですでに支給停止されてから引き続き3年を経過していた場合には、障害厚生年金の受給権は消滅しているため、障害厚生年金は支給されない。"}, {"id": 154, "section": "障害手当金", "q": "傷病に係る初診日において厚生年金保険の被保険者であった者が、保険料納付要件を満たし、かつ初診日から起算して5年を経過するまでの間に、傷病は治ってはいないが症状が固定した状態にあり、政令に定める程度の障害の状態にあるとき、障害手当金が支給される。", "correct": true, "exp": "設問の通り正しい。なお、設問の「傷病は治ってはいないが症状が固定し治療の効果が期待できない状態に至った日」は、「傷病が治った日」に含まれる。"}, {"id": 155, "section": "障害手当金", "q": "障害手当金は、障害の程度を定めるべき日において年金たる保険給付の受給権者（最後に障害等級に該当する程度の障害状態に該当しなくなった日から起算して当該障害状態に該当することなく3年を経過した障害厚生年金の受給権者（現に障害状態に該当しない者に限る。）を除く。）である者には支給しない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 156, "section": "障害手当金", "q": "在職老齢年金の仕組みにより支給停止が行われている老齢厚生年金を受給している65歳の者が、障害の程度を定めるべき日において障害手当金に該当する程度の障害の状態になった場合、障害手当金は支給される。", "correct": false, "exp": "障害の程度を定めるべき日において老齢厚生年金の受給権者である者に障害手当金は支給されない。"}, {"id": 157, "section": "障害手当金", "q": "障害手当金は、その障害の程度を定めるべき日において、当該障害に係る傷病とは異なる傷病について労働基準法の障害補償を受ける権利を有する者には、支給しない。", "correct": false, "exp": "障害手当金は、その障害の程度を定めるべき日において、当該障害に係る傷病（同一の傷病）について労働基準法の障害補償を受ける権利を有する者には、支給しない。"}, {"id": 158, "section": "障害手当金", "q": "障害手当金の額は、原則として厚生年金保険法第50条第1項の規定の例により計算した額の100分の250に相当する額であるが、3級の障害厚生年金の最低保障額の2倍に相当する最低保障額がある。", "correct": false, "exp": "障害手当金の額は、原則として厚生年金保険法第50条第1項の規定の例により計算した額の「100分の200」に相当する額である。"}, {"id": 159, "section": "障害手当金", "q": "障害手当金の額の計算に当たって、給付乗率は生年月日に応じた読み替えは行わず、計算の基礎となる被保険者期間の月数が300か月に満たないときは、これを300か月として計算する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 160, "section": "遺族厚生年金の支給要件", "q": "被保険者であった者が、被保険者の資格を喪失した後5年を経過する目前に、被保険者であった間に初診日がある傷病により死亡したとき、保険料納付要件を満たしている場合には、その者の遺族に遺族厚生年金が支給される。", "correct": false, "exp": "被保険者であった者が、被保険者の資格を喪失した後に、被保険者であった間に初診日がある傷病により「当該初診日から起算して5年を経過する目前」に死亡したとき、保険料納付要件を満たしている場合には、その者の遺族に遺族厚生年金が支給される。"}, {"id": 161, "section": "遺族厚生年金の支給要件", "q": "障害等級1級又は2級に該当する障害の状態にある障害厚生年金の受給権者が死亡したときは、遺族厚生年金の支給要件について、保険料納付要件は問われない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 162, "section": "遺族厚生年金の支給要件", "q": "保険料納付済期間と保険料免除期間とを合算した期間が25年以上である被保険者（障害等級1級又は2級に該当する障害厚生年金の受給権者を除く。）が死亡したときは、その遺族が遺族厚生年金を請求したときに別段の申出をした場合を除き、厚生年金保険法第58条第1項第1号（短期要件）に該当し、同条第1項第4号（長期要件）には該当しないものとみなされる。", "correct": true, "exp": "設問の通り正しい。死亡した被保険者等が短期要件に該当し、かつ、長期要件にも該当するときは、その遺族が遺族厚生年金を請求したときに別段の申出をした場合を除き、短期要件のみに該当し、長期要件には該当しないものとみなす。"}, {"id": 163, "section": "遺族厚生年金の支給要件", "q": "63歳の厚生年金保険の被保険者が令和7年4月に死亡した場合であって、死亡日の前日において、その者について厚生年金保険の被保険者期間があり、かつ、当該被保険者期間に係る保険料納付済期間と保険料免除期間とを合算した期間が当該被保険者期間の3分の2未満であり、保険料納付済期間、保険料免除期間及び合算対象期間を合算した期間が25年に満たないが、60歳から継続して厚生年金保険の被保険者であった場合、死亡した者によって生計を維持していた一定の遺族に遺族厚生年金が支給される。", "correct": true, "exp": "設問の通り正しい。設問の者は、死亡日において厚生年金保険の被保険者であり、また、特例による保険料納付要件を満たすため、その者によって生計を維持していた一定の遺族に遺族厚生年金が支給される。"}, {"id": 164, "section": "遺族厚生年金の支給要件", "q": "船舶が沈没し、転覆し、滅失し、若しくは行方不明となった際現にその船舶に乗っていた被保険者等の生死が3月間わからない場合又はこれらの者の死亡が3月以内に明らかとなり、かつ、その死亡の時期がわからない場合には、遺族厚生年金の支給に関する規定の適用については、その船舶が沈没し、転覆し、滅失し、若しくは行方不明となった日又はその者が行方不明となった日に、その者は、死亡したものと推定する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 165, "section": "遺族厚生年金の支給要件", "q": "老齢厚生年金の受給権者（保険料納付済期間、保険料免除期間及び合算対象期間を合算した期間が25年以上である者に限る。）が行方不明になり、その後失踪の宣告を受けた場合で、遺族厚生年金を支給する際には、当該失踪者が行方不明になった当時の保険料納付要件は問わない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 166, "section": "遺族厚生年金の支給要件", "q": "遺族厚生年金を受けることができる遺族については、父母は、配偶者又は子が、孫は、配偶者、子又は父母が、祖父母は、配偶者、子、父母又は孫が遺族厚生年金の受給権を取得したときは、それぞれ遺族厚生年金を受けることができる遺族としない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 167, "section": "遺族厚生年金の支給要件", "q": "被保険者の死亡により遺族厚生年金の受給権者となった妻が、再婚したことによってその受給権を失ったとき、被保険者の死亡当時その者によって生計を維持していた母がいる場合は、当該母がその遺族厚生年金を受給することができる。", "correct": false, "exp": "設問の母は、妻が遺族厚生年金を受けることができるときは、遺族厚生年金を受けることができる遺族とされないため、妻が遺族厚生年金の受給権を失っても、母に対して遺族厚生年金が支給されることはない。"}, {"id": 168, "section": "遺族厚生年金の額等", "q": "障害等級2級に該当する障害の状態にある障害厚生年金の受給権者が死亡したことにより支給される遺族厚生年金の額の計算の基礎となる被保険者期間の月数が300に満たないときは、これを300として計算する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 169, "section": "遺族厚生年金の額等", "q": "現在55歳の自営業者の甲は、20歳から5年間会社に勤めていたので、厚生年金保険の被保険者期間が5年あり、この他の期間はすべて厚生年金保険の第1号被保険者期間で保険料はすべて納付済みとなっている。もし、甲が現時点で死亡した場合、一定要件を満たす遺族に支給される遺族厚生年金の額は、厚生年金保険の被保険者期間を300月として計算した額となる。", "correct": false, "exp": "甲が現時点で死亡した場合、長期要件に該当する。長期要件に該当することにより支給される遺族厚生年金については、その額の計算の基礎となる被保険者期間の月数が300に満たないときであっても、これを300として計算はせず、実際の被保険者期間の月数（設問の場合、60か月）に基づき計算する。"}, {"id": 170, "section": "遺族厚生年金の額等", "q": "被保険者が死亡したことによる遺族厚生年金の額は、死亡した者の被保険者期間を基礎として計算された老齢厚生年金の額の4分の3に相当する額とする。この額が、遺族基礎年金の額に4分の3を乗じて得た額に満たないときは、当該4分の3を乗じて得た額を遺族厚生年金の額とする。", "correct": false, "exp": "遺族厚生年金の額について、設問のような最低保障額の規定は設けられていない。"}, {"id": 171, "section": "遺族厚生年金の額等", "q": "配偶者以外の者に遺族厚生年金を支給する場合において、受給権者の数に増減を生じたときは、増減を生じた月から、年金の額を改定する。", "correct": false, "exp": "配偶者以外の者に遺族厚生年金を支給する場合において、受給権者の数に増減を生じたときは、増減を生じた月の翌月から、年金の額を改定する。"}, {"id": 172, "section": "遺族厚生年金の額等", "q": "遺族厚生年金（その受給権者が65歳に達しているものに限る。）は、その受給権者が老齢厚生年金の受給権を有するときは、当該老齢厚生年金の額（加給年金額を除く。）に相当する部分の支給を停止する。", "correct": true, "exp": "設問の通り正しい。遺族厚生年金（その受給権者が65歳に達しているものに限る。）と老齢厚生年金は併給することができるが、遺族厚生年金については、老齢厚生年金の額（加給年金額を除く。）に相当する部分の支給を停止するため、実際に受給できる遺族厚生年金の額は、その差額相当額となる。"}, {"id": 173, "section": "遺族厚生年金の額等", "q": "保険料納付済期間、保険料免除期間及び合算対象期間を合算した期間を25年有しない被保険者が死亡した場合において、死亡した者の妻が遺族厚生年金の受給権を取得したときに、夫の死亡当時遺族基礎年金の支給を受けることができる子がいない場合は、当該妻が40歳に達するまでの間、遺族厚生年金の額に遺族基礎年金の額の4分の3に相当する額が加算される。", "correct": false, "exp": "設問の遺族基礎年金の額の4分の3に相当する額（中高齢寡婦加算額）の加算の対象となるのは、その死亡した者の妻であって、①受給権取得当時、40歳以上65歳未満であったもの、②40歳に達した当時、遺族基礎年金を受けることができる遺族の範囲に属する子と生計を同じくしていたものである。40歳未満の者に支給する遺族厚生年金に中高齢寡婦加算額は加算されない。"}, {"id": 174, "section": "遺族厚生年金の額等", "q": "中高齢寡婦加算の額が加算された遺族厚生年金は、その受給権者である妻が当該被保険者又は被保険者であった者の死亡について厚生年金保険法による遺族基礎年金の支給を受けることができるときは、その間、当該中高齢寡婦加算の額に相当する部分の支給を停止する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 175, "section": "遺族厚生年金の支給停止", "q": "遺族厚生年金は、当該被保険者又は被保険者であった者の死亡について労働基準法の規定による遺族補償の支給が行われるべきものであるときは、支給しない。", "correct": false, "exp": "設問の場合、死亡の日から6年間、遺族厚生年金の支給を停止することとされている。"}, {"id": 176, "section": "遺族厚生年金の支給停止", "q": "被保険者の死亡により妻と子に遺族厚生年金の受給権が発生した場合、子に対する遺族厚生年金は、妻が遺族厚生年金の受給権を有する期間、原則として、その支給が停止される。この場合において、妻自身の申出により妻に対する遺族厚生年金の支給が停止されているときであっても、子に対する遺族厚生年金の支給停止は解除されない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 177, "section": "遺族厚生年金の支給停止", "q": "配偶者に対する遺族厚生年金は、当該被保険者又は被保険者であった者の死亡について、配偶者が厚生年金保険法による遺族基礎年金の受給権を有しない場合であって子が当該遺族基礎年金の受給権を有するときは、その間、その支給を停止する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 178, "section": "遺族厚生年金の支給停止", "q": "夫、父母又は祖父母に対する遺族厚生年金は、受給権者が65歳に達するまでの期間、その支給を停止する。", "correct": false, "exp": "夫、父母又は祖父母に対する遺族厚生年金は、受給権者が「60歳」に達するまでの期間、その支給を停止する。"}, {"id": 179, "section": "遺族厚生年金の支給停止", "q": "配偶者又は子に対する遺族厚生年金は、その配偶者又は子の所在が1月以上明らかでないときは、遺族厚生年金の受給権を有する子又は配偶者の申請によって、その所在が明らかでなくなった時にさかのぼって、その支給を停止する。", "correct": false, "exp": "設問の「1月」を「1年」に置き換えると正しい記述となる。"}, {"id": 180, "section": "遺族厚生年金の失権等", "q": "遺族厚生年金における子の受給権は、当該子が母と再婚した夫（直系姻族）の養子となったことを理由として消滅することはない。", "correct": true, "exp": "設問の通り正しい。なお、子が直系血族又は直系姻族以外の者の養子となったときは、当該子の有する遺族厚生年金の受給権は消滅する。"}, {"id": 181, "section": "遺族厚生年金の失権等", "q": "被保険者であった者の死亡により、死亡した者の子（障害等級1級又は2級に該当する者を除く。）が遺族厚生年金の受給権者となった場合において、その後当該子が10歳で父方の祖父の養子となった場合でも、18歳に達する日以後の最初の3月31日が終了するまでは受給権は消滅しない。", "correct": true, "exp": "設問の通り正しい。「父方の祖父」は直系血族に当たるため、その者の養子となった場合でも、他の失権事由に該当しない限り、遺族厚生年金の受給権は消滅しない。"}, {"id": 182, "section": "遺族厚生年金の失権等", "q": "遺族厚生年金の受給権を取得した当時30歳未満である妻が、当該遺族厚生年金と同一の支給事由に基づく遺族基礎年金の受給権を取得しない場合、当該遺族厚生年金の受給権を取得した日から5年を経過したときに、その受給権は消滅する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 183, "section": "遺族厚生年金の失権等", "q": "遺族厚生年金の受給権は、遺族厚生年金と当該遺族厚生年金と同一の支給事由に基づく厚生年金保険法による遺族基礎年金の受給権を有する妻が30歳に到達する目前に当該遺族基礎年金の受給権が消滅したときは、当該遺族基礎年金の受給権が消滅した日から起算して5年を経過したときに、消滅する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 184, "section": "遺族厚生年金の失権等", "q": "老齢厚生年金の受給権者（保険料納付済期間、保険料免除期間及び合算対象期間を合算した期間が25年以上である者に限る。）が死亡したことにより当該死亡者の子または孫が遺族厚生年金の受給権者となった場合において、当該子または孫が障害等級の3級に該当する障害の状態にあるときであっても、18歳に達した日以後の最初の3月31日が終了したときに当該遺族厚生年金の受給権は消滅する。", "correct": true, "exp": "設問の通り正しい。遺族厚生年金の受給権者である子又は孫は、障害等級3級に該当する障害状態であるので、18歳に達した日以後の最初の3月31日が終了したときに受給権は消滅する。"}, {"id": 185, "section": "遺族厚生年金の失権等", "q": "父母、孫又は祖父母の遺族厚生年金は、被保険者又は被保険者であった者の死亡の当時胎児であった子が出生したときは、その支給を停止する。", "correct": false, "exp": "設問の場合には、父母、孫又は祖父母の有する遺族厚生年金の受給権は消滅する。"}, {"id": 186, "section": "遺族厚生年金の失権等", "q": "被保険者又は被保険者であった者の死亡の当時胎児であった子が出生したときは、妻の遺族厚生年金の受給権は消滅する。", "correct": false, "exp": "配偶者と子は同順位であるから、被保険者又は被保険者であった者の死亡の当時胎児であった子が出生しても、妻の有する遺族厚生年金の受給権は消滅しない。"}, {"id": 187, "section": "遺族厚生年金の失権等", "q": "平成8年4月1日前に死亡した被保険者の死亡について、被保険者の死亡の当時その者によって生計を維持していた55歳未満の夫であって障害等級2級以上に該当する障害の状態にあることにより遺族厚生年金が支給されているものについては、その障害の状態がやんだときは、当該遺族厚生年金の受給権は消滅する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 188, "section": "脱退一時金", "q": "老齢厚生年金の受給資格期間を満たしているが、受給開始年齢に達していないため、老齢厚生年金の支給を受けていない日本国籍を有しない者は、脱退一時金を請求することができる。", "correct": false, "exp": "老齢厚生年金の受給資格期間を満たしている者は、脱退一時金の支給を請求することはできない。"}, {"id": 189, "section": "脱退一時金", "q": "日本国籍を有しない者が障害手当金の受給権を有したことがある場合であっても、脱退一時金を請求することができる。", "correct": false, "exp": "障害手当金の受給権を有したことがある者は、脱退一時金の支給を請求することはできない。"}, {"id": 190, "section": "脱退一時金", "q": "日本国籍を有しない者が最後に厚生年金保険の被保険者の資格を喪失した日（同日において日本国内に住所を有していた者にあっては、同日後初めて、日本国内に住所を有しなくなった日）から起算して1年を経過しているときは、脱退一時金を請求することができない。", "correct": false, "exp": "脱退一時金を請求することができないのは、最後に厚生年金保険の被保険者の資格を喪失した日から起算して「2年」を経過しているときである。"}, {"id": 191, "section": "脱退一時金", "q": "2以上の種別の被保険者であった期間を有する者の脱退一時金は、それぞれの種別の被保険者であった期間ごとに6か月以上の期間がなければ受給資格を得ることはできない。", "correct": false, "exp": "2以上の種別の被保険者であった期間を有する者に係る脱退一時金の支給要件については、その者の2以上の被保険者の種別に係る被保険者であった期間に係る被保険者期間を合算し、一の期間に係る被保険者期間のみを有する者に係るものとみなして判定する。"}, {"id": 192, "section": "脱退一時金", "q": "脱退一時金の額の計算に使用される支給率の計算の基礎となる「政令で定める数」の上限は36である。", "correct": false, "exp": "設問の政令で定める数の上限は「60」である。"}, {"id": 193, "section": "脱退一時金", "q": "脱退一時金の支給要件には回数に関する制限がある。", "correct": false, "exp": "脱退一時金の支給要件には、回数に関する制限はない。"}, {"id": 194, "section": "保険給付の通則等", "q": "政府は、少なくとも5年ごとに、保険料及び国庫負担の額並びに厚生年金保険法による保険給付に要する費用の額その他の厚生年金保険事業の財政に係る収支についてその現況及び財政均衡期間における見通しを作成しなければならない。", "correct": true, "exp": "設問の通り正しい。なお、設問の財政均衡期間は、財政の現況及び見通しが作成される年以降おおむね100年間とされている。"}, {"id": 195, "section": "保険給付の通則等", "q": "厚生年金保険法による年金たる保険給付の額は、国民の生活水準、賃金その他の諸事情に著しい変動が生じた場合には、変動後の諸事情に応ずるため、速やかに改定の措置が講ぜられなければならない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 196, "section": "保険給付の通則等", "q": "調整期間以外の期間に係る新規裁定者の再評価率については、毎年度、原則として、名目手取り賃金変動率を基準として改定し、当該年度の4月以降の保険給付について適用する。", "correct": true, "exp": "設問の通り正しい。なお、受給権者が65歳に達した日の属する年度の初日の属する年の3年後の年の4月1日の属する年度以後において適用される再評価率（「基準年度以後再評価率」という。）の改定については、設問の規定にかかわらず、原則として、物価変動率を基準とする。"}, {"id": 197, "section": "保険給付の通則等", "q": "保険給付の受給権者が死亡した場合において、その死亡した者に支給すべき保険給付でまだその者に支給しなかったものがあるときは、その者の配偶者、子、父母、孫、祖父母、兄弟姉妹又はこれらの者以外の3親等内の親族であって、その者の死亡の当時その者と生計を同じくしていたものは、自己の名で、その未支給の保険給付の支給を請求することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 198, "section": "保険給付の通則等", "q": "障害手当金の支給要件を満たした者が死亡した場合において、その者が死亡前に当該障害手当金を請求していなかったときは、その者の配偶者であって、その者の死亡の当時その者と生計を同じくしていたものは、自己の名で、その障害手当金を請求することができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 199, "section": "保険給付の通則等", "q": "保険給付の受給権者の死亡に係る未支給の保険給付がある場合であって、当該未支給の保険給付を受けるべき同順位者が2人以上あるときは、当該同順位者の数で按分した額をそれぞれに支給する。", "correct": false, "exp": "「未支給の保険給付を受けるべき同順位者が2人以上あるときは、その1人のした請求は、全員のためその全額につきしたものとみなし、その1人に対してした支給は、全員に対してしたものとみなす。」とされており、同順位者の数で按分した額をそれぞれに支給するわけではない。"}, {"id": 200, "section": "保険給付の通則等", "q": "障害基礎年金の受給権者である男性が65歳で遺族厚生年金の受給権を得た場合、それぞれを併給することができる。", "correct": true, "exp": "設問の通り正しい。障害基礎年金と遺族厚生年金は、受給権者が65歳に達しているときは、併給することができる。"}, {"id": 201, "section": "保険給付の通則等", "q": "障害厚生年金は、老齢基礎年金及び付加年金並びに当該障害厚生年金と同一の支給事由に基づいて支給される障害基礎年金と併給できるが、遺族基礎年金とは併給できない。", "correct": false, "exp": "障害厚生年金は、「老齢基礎年金及び付加年金」と併給することもできない。なお、障害基礎年金及び遺族基礎年金との併給に関する記述は正しい。"}, {"id": 202, "section": "保険給付の通則等", "q": "年金たる保険給付（厚生年金保険法の他の規定又は他の法令の規定によりその全額につき支給を停止されている年金たる保険給付を除く。）は、その受給権者の申出により、原則として、その全額の支給を停止する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 203, "section": "保険給付の通則等", "q": "受給権者（2以上の種別の被保険者であった期間を有する者を除く。）の申出による年金たる保険給付の支給停止について、この申出は、老齢基礎年金と老齢厚生年金のような支給事由が同一の年金がある場合には同時に行わなければならない。", "correct": false, "exp": "設問のような規定はない。"}, {"id": 204, "section": "保険給付の通則等", "q": "一の被保険者の種別に係る被保険者であった期間に基づく障害等級1級又は2級の障害厚生年金の受給権者が、新たに当該一の期間に基づく障害等級1級又は2級に該当する障害を受け、厚生年金保険法第48条第1項の規定に基づいて、前後の障害を併合した障害の程度による新たな障害厚生年金の受給権を取得した場合、従前の障害厚生年金の受給権が消滅した月の翌月以後の分として、従前の障害厚生年金の支払が行われたときは、その支払われた従前の障害厚生年金は、新たな障害厚生年金の内払とみなす。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 205, "section": "保険給付の通則等", "q": "一の被保険者の種別に係る被保険者であった期間に基づく遺族厚生年金の受給権者が当該一の期間に基づく障害厚生年金の受給権を取得し、障害厚生年金の支給を選択した場合において、遺族厚生年金の支給を停止すべき事由が生じた月の翌月以後の分として遺族厚生年金の支払が行われたときは、その支払われた遺族厚生年金は、障害厚生年金の内払とみなす。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 206, "section": "保険給付の通則等", "q": "同一人に対して厚生年金保険法による寡婦年金の支給を停止して60歳台前半の老齢厚生年金（厚生労働大臣が支給するものに限る。）を支給すべき場合において、老齢厚生年金を支給すべき事由が生じた月の翌月以後の分として寡婦年金の支払が行われたときは、その寡婦年金は、老齢厚生年金の内払とみなすことができる。", "correct": true, "exp": "設問の通り正しい。同一人に対する内払調整は、厚生年金保険法の年金たる保険給付（厚生労働大臣が支給するものに限る。）と厚生年金保険法による年金たる給付の間でも行われる。"}, {"id": 207, "section": "保険給付の通則等", "q": "老齢厚生年金の受給権者に対し、在職老齢年金の仕組みにより、当該年金の支給を停止すべき事由が生じたにもかかわらず、その停止すべき期間の分として当該年金が支払われたときは、その支払われた年金は、その後に支払うべき当該年金の内払とみなすことができる。", "correct": true, "exp": "設問の通り正しい。年金の支給を停止すべき事由が生じたにもかかわらず、その停止すべき期間の分として年金が支払われたときは、その支払われた年金は、その後に支払うべき年金の内払とみなすことができる。"}, {"id": 208, "section": "保険給付の通則等", "q": "障害厚生年金の受給権者が死亡したにもかかわらず、当該障害厚生年金の給付に過誤払いが生じた場合、返還金請求権に係る債務を弁済すべき者に支払うべき老齢厚生年金の支払金の金額を当該過誤払いによる返還金債権の金額に充当することができる。", "correct": false, "exp": "「老齢厚生年金の支払金の金額を当該過誤払いによる返還金債権の金額に充当すること」はできない。過誤払いによる返還金債権の金額に充当することができるのは、年金たる保険給付の受給権者の死亡を支給事由とする遺族厚生年金（当該年金たる保険給付と同一の実施機関が支給するものに限る。）の支払金の金額である。"}, {"id": 209, "section": "保険給付の通則等", "q": "障害手当金として保険給付を受ける権利は、譲り渡し、担保に供し、又は差し押さえることはできない。", "correct": true, "exp": "設問の通り正しい。保険給付を受ける権利は、譲り渡し、担保に供し、又は差し押えることができない。ただし、老齢厚生年金、脱退手当金及び脱退一時金を受ける権利を国税滞納処分（その例による処分を含む。）により差し押える場合は、この限りでない。"}, {"id": 210, "section": "保険給付の通則等", "q": "遺族厚生年金として支給を受けた金銭を標準として、租税その他の公課を課すことができる。", "correct": false, "exp": "遺族厚生年金として支給を受けた金銭を標準として、租税その他の公課を課すことはできない。ただし、老齢厚生年金及び脱退手当金については、この限りでない。"}, {"id": 211, "section": "保険給付の通則等", "q": "被保険者が、自己の故意の犯罪行為により、死亡の原因となった事故を生じさせたときは、保険給付の全部又は一部を行なわないことができることとなっており、被保険者が精神疾患のため自殺した場合には遺族厚生年金は支給されない。", "correct": false, "exp": "自殺は故意の犯罪行為に該当しないため、設問の給付制限の対象とはならない。自殺行為は何らかの精神異常に起因して行われる場合が多く、これをもって直ちに故意に保険事故を発生せしめたものとして給付制限を行うことは適当ではないと考えられている。"}, {"id": 212, "section": "保険給付の通則等", "q": "老齢厚生年金（第1号厚生年金被保険者期間に基づくものとする。）の受給権者が、正当な理由がなくて、厚生年金保険法施行規則の規定により行わなければならない届出またはこれに添えるべき書類を提出しない場合には、保険給付の全部または一部を一時停止することができる。", "correct": false, "exp": "設問の受給権者が、正当な理由がなくて、厚生労働省令の定める事項について届出をせず、又は書類その他の物件を提出しないときは、保険給付の「全部又は一部を一時停止する」のではなく、「支払を一時差し止める」ことができる。"}, {"id": 213, "section": "離婚時の年金分割", "q": "標準報酬改定請求は、平成19年4月1日前の対象期間に係る標準報酬も改定又は決定の対象としている。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 214, "section": "離婚時の年金分割", "q": "いわゆる合意分割に係る標準報酬改定請求をすること及び請求すべき按分割合について第1号改定者及び第2号改定者の合意のための協議が調わないときは、当事者の一方の申立てにより、簡易裁判所が、請求すべき按分割合を定めることができる。", "correct": false, "exp": "設問の場合には、当事者の一方の申立てにより、「家庭裁判所」が、当該対象期間における保険料納付に対する当事者の寄与の程度その他一切の事情を考慮して、請求すべき按分割合を定めることができることとされている。"}, {"id": 215, "section": "離婚時の年金分割", "q": "標準報酬改定請求に係る請求すべき按分割合は、当事者それぞれの対象期間標準報酬総額の合計額に対する第2号改定者の対象期間標準報酬総額の割合を超え3分の2以下の範囲内で定められなければならない。", "correct": false, "exp": "標準報酬改定請求に係る請求すべき按分割合は、当事者それぞれの対象期間標準報酬総額の合計額に対する第2号改定者の対象期間標準報酬総額の割合を超え「2分の1」以下の範囲内で定められなければならない。"}, {"id": 216, "section": "離婚時の年金分割", "q": "離婚時みなし被保険者期間は、60歳台前半の老齢厚生年金の支給要件（1年以上の被保険者期間を有すること）に係る被保険者期間に含まれる。", "correct": false, "exp": "60歳台前半の老齢厚生年金の支給要件の一つである「1年以上の被保険者期間を有すること」について、当該被保険者期間から離婚時みなし被保険者期間は除かれている。"}, {"id": 217, "section": "離婚時の年金分割", "q": "いわゆる「離婚時の第3号被保険者期間についての厚生年金保険の分割」の対象となる特定期間とは、特定被保険者が被保険者であった期間であり、かつ、その被扶養配偶者が当該特定被保険者の配偶者として厚生年金保険の第3号被保険者であった期間をいい、平成20年4月1日前の期間を含まない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 218, "section": "離婚時の年金分割", "q": "特定被保険者が障害厚生年金の受給権者であっても、特定期間の一部のみがその額の計算の基礎となっている場合には、当該特定被保険者の被扶養配偶者は、特定期間のうち障害厚生年金の額の計算の基礎となっていた被保険者期間を除いて、3号分割標準報酬改定請求をすることができる。", "correct": true, "exp": "設問の通り正しい。なお、3号分割標準報酬改定請求は、その請求日において特定被保険者が特定期間の全部をその額の計算の基礎とする障害厚生年金の受給権者である場合には、することができない。"}, {"id": 219, "section": "離婚時の年金分割", "q": "原則として、離婚が成立した日等の翌日から起算して2年を経過したときは、被扶養配偶者からの特定期間に係る被保険者期間の標準報酬の改定及び決定の請求を行うことができない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 220, "section": "不服申立て・雑則等", "q": "被保険者の資格または標準報酬に関する処分が確定したときは、その処分についての不服を当該処分に基づく保険給付に関する処分についての不服の理由とすることができる。", "correct": false, "exp": "被保険者の資格又は標準報酬に関する処分が確定したときは、その処分についての不服を当該処分に基づく保険給付に関する処分についての不服の理由とすることができない。"}, {"id": 221, "section": "不服申立て・雑則等", "q": "第1号厚生年金被保険者に係る厚生労働大臣による保険料の滞納処分に不服がある者は社会保険審査官に対して、審査請求をすることができる。", "correct": false, "exp": "第1号厚生年金被保険者に係る厚生労働大臣による保険料の滞納処分に不服がある者は、「社会保険審査会」に対して、審査請求をすることができる。"}, {"id": 222, "section": "不服申立て・雑則等", "q": "海外に在住している日本国籍を有しない者で厚生労働大臣による脱退一時金に関する処分を受けた者が、当該処分について不服がある場合には、社会保険審査会に審査請求をすることができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 223, "section": "不服申立て・雑則等", "q": "保険料その他厚生年金保険法の規定による徴収金を徴収し、又はその還付を受ける権利は、これらを行使することができる時から5年を経過したとき、時効によって、消滅する。", "correct": false, "exp": "保険料その他厚生年金保険法の規定による徴収金を徴収し、又はその還付を受ける権利は、これらを行使することができる時から「2年」を経過したとき、時効によって、消滅する。"}, {"id": 224, "section": "不服申立て・雑則等", "q": "保険給付を受ける権利は、その支給すべき事由が生じた日から3年を経過したときは、時効によって、消滅する。", "correct": false, "exp": "保険給付を受ける権利は、その支給すべき事由が生じた日から「5年」を経過したときは、時効によって、消滅する。"}, {"id": 225, "section": "不服申立て・雑則等", "q": "保険給付を受ける権利に基づき支払期月ごとに支払うものとされる保険給付の支給を受ける権利については、「支払期月の翌月の初日」がいわゆる時効の起算点とされ、各起算点となる日から5年を経過したときに時効によって消滅する。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 226, "section": "不服申立て・雑則等", "q": "年金たる保険給付を受ける権利の時効は、当該年金たる保険給付がその全額につき支給を停止されたときは、進行しない。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 227, "section": "不服申立て・雑則等", "q": "厚生年金保険法第95条において、「市町村長は、実施機関又は受給権者に対して、当該市町村の条例の定めるところにより、被保険者、被保険者であった者又は受給権者の戸籍に関し、有料で証明を行うことができる。」と規定されている。", "correct": false, "exp": "市町村長は、実施機関又は受給権者に対して、当該市町村の条例の定めるところにより、被保険者、被保険者であった者又は受給権者の戸籍に関し、「無料」で証明を行うことができる。"}, {"id": 228, "section": "不服申立て・雑則等", "q": "実施機関は、必要があると認めるときは、障害等級に該当する程度の障害の状態にあることにより、年金たる保険給付の受給権を有し、又は厚生年金保険法第44条第1項の規定によりその者について加給年金額の加算が行われている子に対して、その指定する医師の診断を受けるべきことを命じ、又は当該職員をしてこれらの者の障害の状態を診断させることができる。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 229, "section": "不服申立て・雑則等", "q": "第1号厚生年金被保険者を使用する事業主が、正当な理由がなく厚生年金保険法第27条の規定に違反して、厚生労働大臣に対し、当該被保険者に係る報酬月額及び賞与額に関する事項を届け出なければならないにもかかわらず、これを届け出なかったときは、6か月以下の懲役又は50万円以下の罰金に処する旨の罰則が定められている。", "correct": true, "exp": "設問の通り正しい。"}, {"id": 230, "section": "不服申立て・雑則等", "q": "事業主は、正当な理由がなくて納付すべき自己の負担する保険料及びその使用する被保険者の保険料の納付を怠り、督促状に指定する期限までにこれを納付しないときは、30万円以下の罰金に処せられる。", "correct": false, "exp": "設問の場合、6月以下の懲役又は50万円以下の罰金に処せられる。"}];
